"""ABHA-related APIs.Contains APIs for OTP requests and ABHA enrollment workflows."""import requestsfrom config import ABHA_BASE_URLfrom utils import generate_request_id, generate_timestampdef request_otp(token,    action,    scope,    login_hint,    login_id,    otp_system="aadhaar",    txn_id="",    x_token=None,):    """    Request an OTP for an ABDM workflow.    Args:        token (str): Gateway bearer token.        action (str): profile/login, enrollment, etc.        scope (list): API scope.        login_hint (str): aadhaar, mobile, abha-number, etc.        login_id (str): Usually an encrypted value.        otp_system (str): aadhaar, mobile, etc.        txn_id (str, optional): Transaction ID if required.        x_token (str, optional): User X-Token.    Returns:        requests.Response    """    url = f"{ABHA_BASE_URL}/{action}/request/otp"    headers = {        "REQUEST-ID": generate_request_id(),        "TIMESTAMP": generate_timestamp(),        "Authorization": f"Bearer {token}",        "Content-Type": "application/json",    }    if x_token:        headers["X-Token"] = f"Bearer {x_token}"    payload = {        "scope": scope,        "loginHint": login_hint,        "loginId": login_id,        "otpSystem": otp_system,        "txnId": txn_id,    }    response = requests.post(        url=url,        headers=headers,        json=payload,    )    return response    def enroll_by_aadhaar(    token,    txn_id,    otp_value,    mobile,    consent_code="abha-enrollment",    consent_version="1.4",):    """    Complete ABHA enrollment using Aadhaar OTP.    Args:        token (str): Gateway bearer token.        txn_id (str): Transaction ID returned by request_otp().        otp_value (str): RSA encrypted OTP.        mobile (str): Mobile number.        consent_code (str): Consent code.        consent_version (str): Consent version.    Returns:        requests.Response    """    url = f"{ABHA_BASE_URL}/enrollment/enrol/byAadhaar"    headers = {        "REQUEST-ID": generate_request_id(),        "TIMESTAMP": generate_timestamp(),        "Authorization": f"Bearer {token}",        "Content-Type": "application/json",    }    payload = {        "authData": {            "authMethods": ["otp"],            "otp": {                "timeStamp": generate_timestamp(),                "txnId": txn_id,                "otpValue": otp_value,                "mobile": mobile,            },        },        "consent": {            "code": consent_code,            "version": consent_version,        },    }    response = requests.post(        url=url,        headers=headers,        json=payload,    )    return response    def request_email_verification_link(    token,    x_token,    action,    scope,    login_hint,    login_id,    otp_system="abdm",):    """    Request an email verification link for an ABDM workflow.    Args:        token (str): Gateway bearer token.        x_token (str): User X-Token.        action (str): API path after /v3/.            Example: "profile/account"        scope (list): Workflow scope.        login_hint (str): Usually "email".        login_id (str): Encrypted email address.        otp_system (str): OTP system. Default is "abdm".    Returns:        requests.Response    """    url = f"{ABHA_BASE_URL}/{action}/request/emailVerificationLink"    headers = {        "Authorization": f"Bearer {token}",        "X-Token": f"Bearer {x_token}",        "REQUEST-ID": generate_request_id(),        "TIMESTAMP": generate_timestamp(),        "Content-Type": "application/json",    }    payload = {        "scope": scope,        "loginHint": login_hint,        "loginId": login_id,        "otpSystem": otp_system,    }    response = requests.post(        url=url,        headers=headers,        json=payload,    )    return response    def verify_mobile_linking_otp(    token,    action,    scope,    txn_id,    otp_value,    auth_method="otp",):    """    Verify OTP to Link Mobile using the ABDM authentication service.    Args:        token (str): Gateway bearer token.        action (str): API path after /v3/.            Example: "enrollment/auth"        scope (list): Workflow scope.            Example: ["abha-enrol", "mobile-verify"]        txn_id (str): Transaction ID returned by request_otp().        otp_value (str): RSA encrypted OTP.        auth_method (str): Authentication method. Default is "otp".    Returns:        requests.Response    """    url = f"{ABHA_BASE_URL}/{action}/auth/byAbdm"    headers = {        "Authorization": f"Bearer {token}",        "REQUEST-ID": generate_request_id(),        "TIMESTAMP": generate_timestamp(),        "Content-Type": "application/json",    }    payload = {        "scope": scope,        "authData": {            "authMethods": [auth_method],            "otp": {                "timeStamp": generate_timestamp(),                "txnId": txn_id,                "otpValue": otp_value,            },        },    }    response = requests.post(        url=url,        headers=headers,        json=payload,    )    return response    def verify_otp(    token,    action,    scope,    txn_id,    otp_value,    auth_method="otp",    x_token=None,):    """    Verify an OTP for an ABDM workflow.    Args:        token (str): Gateway bearer token.        action (str): API path after /v3/.            Examples:                "profile/login"                "profile/account"        scope (list): Workflow scope.            Examples:                ["abha-login", "aadhaar-verify"]                ["account-delete"]        txn_id (str): Transaction ID returned by request_otp().        otp_value (str): RSA encrypted OTP.        auth_method (str): Authentication method. Default is "otp".        x_token (str, optional): User X-Token.    Returns:        requests.Response    """    url = f"{ABHA_BASE_URL}/{action}/verify"    headers = {        "REQUEST-ID": generate_request_id(),        "TIMESTAMP": generate_timestamp(),        "Authorization": f"Bearer {token}",        "Content-Type": "application/json",    }    if x_token:        headers["X-Token"] = f"Bearer {x_token}"    payload = {        "scope": scope,        "authData": {            "authMethods": [auth_method],            "otp": {                "txnId": txn_id,                "otpValue": otp_value,            },        },    }    response = requests.post(        url=url,        headers=headers,        json=payload,    )    return response    def verify_user(    token,    t_token,    action,    abha_number,    txn_id,):    """    Verify the selected ABHA user for an ABDM workflow.    Args:        token (str): Gateway bearer token.        t_token (str): Temporary T-Token returned during login.        action (str): API path after /v3/.            Example: "profile/login"        abha_number (str): Selected ABHA number.        txn_id (str): Transaction ID.    Returns:        requests.Response    """    url = f"{ABHA_BASE_URL}/{action}/verify/user"    headers = {        "Authorization": f"Bearer {token}",        "T-Token": f"Bearer {t_token}",        "REQUEST-ID": generate_request_id(),        "TIMESTAMP": generate_timestamp(),        "Content-Type": "application/json",    }    payload = {        "ABHANumber": abha_number,        "txnId": txn_id,    }    response = requests.post(        url=url,        headers=headers,        json=payload,    )    return responsedef search_abha_by_mobile(    token,    action,    scope,    mobile,):    """    Search for ABHA accounts using a mobile number.    Args:        token (str): Gateway bearer token.        action (str): API path after /v3/.            Example: "profile/account"        scope (list): Workflow scope.            Example: ["search-abha"]        mobile (str): RSA encrypted mobile number.    Returns:        requests.Response    """    url = f"{ABHA_BASE_URL}/{action}/abha/search"    headers = {        "Authorization": f"Bearer {token}",        "REQUEST-ID": generate_request_id(),        "TIMESTAMP": generate_timestamp(),        "Content-Type": "application/json",    }    payload = {        "scope": scope,        "mobile": mobile,    }    response = requests.post(        url=url,        headers=headers,        json=payload,    )    return response    def search_abha_by_address(    token,    action,    abha_address,):    """    Search for an ABHA account using an ABHA Address.    Args:        token (str): Gateway bearer token.        action (str): API path after /v3/.            Example: "phr/web/login"        abha_address (str): ABHA Address to search.    Returns:        requests.Response    """    url = f"{ABHA_BASE_URL}/{action}/abha/search"    headers = {        "Authorization": f"Bearer {token}",        "REQUEST-ID": generate_request_id(),        "TIMESTAMP": generate_timestamp(),        "Content-Type": "application/json",    }    payload = {        "abhaAddress": abha_address,    }    response = requests.post(        url=url,        headers=headers,        json=payload,    )    return response    def get_resource(    token,    x_token,    action="profile/account",    resource=None,):    """    Retrieve an ABDM resource.    Args:        token (str): Gateway bearer token.        x_token (str): User X-Token.        action (str): API path after /v3/.            Default: "profile/account"        resource (str, optional): Resource to retrieve.            Examples:                None -> Profile                "qrCode" -> QR Code                "abha-card" -> ABHA Card    Returns:        requests.Response    """    url = f"{ABHA_BASE_URL}/{action}"    if resource:        url = f"{url}/{resource}"    headers = {        "Authorization": f"Bearer {token}",        "X-Token": f"Bearer {x_token}",        "REQUEST-ID": generate_request_id(),        "TIMESTAMP": generate_timestamp(),    }    response = requests.get(        url=url,        headers=headers,    )    return response    def get_profile(token, x_token):    return get_resource(token, x_token)def get_qr_code(token, x_token):    return get_resource(token, x_token, resource="qrCode")def get_abha_card(token, x_token):    return get_resource(token, x_token, resource="abha-card")